// === Tab: mySketch ===
let nDepth = 9;
let nBranches = 5;
let lengthScale = 0.6;
let tilt = -0.4;
let spread = 0.7;
let hueOffset = 0;

let treeShdr;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	treeShdr = createShader( vsDraw, fsDraw );
}

function draw() {
	let t = frameCount/360;
	scale( width / 5.0 );
	translate( 0, 1 );
	rotate(-TAU/4);
	background(0);
	treeShdr.bindShader();
  treeShdr.setUniform( 'nBranches', nBranches );
  treeShdr.setUniform( 'tilt', t*0.618034 );
  treeShdr.setUniform( 'spread', t );
  treeShdr.setUniform( 'hueOffset', t*0.1276 );
  treeShdr.setUniform( 'lengthScale', lengthScale );
  treeShdr.setUniform( 'thickness', 0.03 );
	let gl = this._renderer.GL;
	gl.disable( gl.DEPTH_TEST );
	gl.enable( gl.BLEND );
	gl.blendEquation( gl.MAX );
	for( let iDepth=0; iDepth<nDepth; iDepth++ ) {
		let nEdges = Math.pow( nBranches, iDepth );
		//console.log( iDepth + " " + nEdges );
		treeShdr.setUniform( 'iDepth', iDepth );
    gl.drawArraysInstanced( gl.TRIANGLE_STRIP, 0, 4, nEdges );
	}
	treeShdr.unbindShader();
}

let vsDraw = `#version 300 es
precision highp float;
precision highp int;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform int iDepth;
uniform int nBranches;
uniform float tilt;
uniform float spread;
uniform float thickness;
uniform float hueOffset;
uniform float lengthScale;
out vec4 vColor;

#define TAU 6.283185307179586
vec2 rot2( vec2 p, float a ) {
  return cos(a)*p + sin(a)*vec2(-p.y, p.x);
}

// http://www.jcgt.org/published/0009/03/02/
// https://www.shadertoy.com/view/XlGcRh
uvec4 pcg4d( uvec4 v ) {
  v = v * 1664525u + 1013904223u;
  v.x += v.y*v.w;  v.y += v.z*v.x;  v.z += v.x*v.y;  v.w += v.y*v.z;
  v ^= v >> 16u;
  v.x += v.y*v.w;  v.y += v.z*v.x;  v.z += v.x*v.y;  v.w += v.y*v.z;
  return v;
}
vec4 pcg4df( int a, int b, int c, int d ) {
  return vec4( pcg4d( uvec4( a, b, c, d ) ) ) / float( 0xffffffffU );
}

vec3 hsb2rgb( in vec3 c ) {
   vec3 rgb = clamp(abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),
                            6.0)-3.0)-1.0,  0.0,  1.0 );
   rgb = rgb*rgb*(3.0-2.0*rgb);
   return c.z * mix( vec3(1.0), rgb, c.y);
}

void main() {
  int idx = gl_InstanceID;
	vec2 p = vec2( float(gl_VertexID&1), float((gl_VertexID&2)/2) );
	p *= vec2( thickness+1.0, thickness );
	p -= thickness * 0.5;
	for( int id=iDepth; id>0; id-- ) {
	  p *= lengthScale;
	  int iBranch = idx % nBranches;
		float ang = tilt + float(iBranch) * spread;
		p = rot2( p, ang );
		p.x += 1.;
		idx /= nBranches;
	}

  vec4 p4 = vec4( p, 0., 1. );
  gl_Position = uProjectionMatrix * uModelViewMatrix * p4;
	float u = float(iDepth+(gl_VertexID&1))/float(10);
	//u = float(gl_InstanceID) / pow(float(nBranches), float(iDepth) );
	vec3 c = hsb2rgb( vec3( u+hueOffset, 0.6, 1. ) );
	vColor = vec4( c, 1.0 );
}
`;

let fsDraw = `#version 300 es
precision highp float;
in vec4 vColor;
out vec4 fragColor;
void main() {
	fragColor = vColor;
}
`;

